"use client";

import { BLUEPRINT_SEED } from "@/app/lib/blueprintSeed";
import { useCountUp } from "@/app/lib/useCountUp";
import { formatINR } from "@/app/lib/formatINR";
import { motion } from "framer-motion";

export function TotalBalanceReadout() {
  const shown = useCountUp(BLUEPRINT_SEED.totalBalance);

  return (
    <section aria-label="Total balance" className="rubric-panel carbon-face checkered-sweep relative overflow-hidden rounded-lg border border-line p-5">
      <p className="num text-[10px] tracking-[0.2em] text-dim">TOTAL BALANCE</p>
      <p className="num mt-1 text-4xl font-bold text-amber">{formatINR(Math.round(shown))}</p>
      <motion.div className="mt-4 h-[3px] rounded bg-amber/70"
        initial={{ scaleX: 0 }} animate={{ scaleX: 1 }}
        style={{ transformOrigin: "left" }}
        transition={{ duration: 1.1, ease: [0.16, 1, 0.3, 1] }} />
    </section>
  );
}
